CREATE FUNCTION public.blog_metrics() RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF public.blog_role() NOT IN ('admin','editor') OR public.blog_role() IS NULL THEN RAISE EXCEPTION 'Editor access required'; END IF;
SELECT jsonb_build_object('published',(SELECT count(*) FROM content_posts WHERE status='published'),'drafts',(SELECT count(*) FROM content_posts WHERE status IN ('draft','in_review')),'scheduled',(SELECT count(*) FROM content_posts WHERE status='scheduled'),'views',(SELECT count(*) FROM content_events WHERE event_type='blog_view'),'visitors',(SELECT count(DISTINCT session_id) FROM content_events WHERE event_type='blog_view'),'engaged',(SELECT count(*) FROM content_events WHERE event_type='blog_engaged'),'ctaClicks',(SELECT count(*) FROM content_events WHERE event_type='blog_cta'),'subscriptions',(SELECT count(*) FROM blog_subscriptions),'registrations',NULL,'top',(SELECT coalesce(jsonb_agg(t),'[]') FROM (SELECT p.id,p.title,p.slug,p.topic,count(e.id) AS views FROM content_posts p LEFT JOIN content_events e ON e.slug=p.slug AND e.event_type='blog_view' WHERE p.status='published' GROUP BY p.id ORDER BY count(e.id) DESC LIMIT 10) t),'trend',(SELECT coalesce(jsonb_agg(t),'[]') FROM (SELECT d::date AS day,count(e.id) AS views FROM generate_series(current_date-29,current_date,'1 day') d LEFT JOIN content_events e ON e.created_at>=d AND e.created_at<d+interval '1 day' AND e.event_type='blog_view' GROUP BY d ORDER BY d) t),'sources',(SELECT coalesce(jsonb_agg(t),'[]') FROM (SELECT coalesce(props->>'source','direct') AS source,count(*) AS views FROM content_events WHERE event_type='blog_view' AND created_at>=now()-interval '30 days' GROUP BY 1 ORDER BY 2 DESC LIMIT 20) t)) INTO result; RETURN result; END $$;
REVOKE ALL ON FUNCTION public.blog_metrics() FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.blog_metrics() TO authenticated;
CREATE FUNCTION public.blog_record_event(_slug text,_event text,_session text,_source text) RETURNS boolean LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF _event NOT IN ('blog_view','blog_engaged','blog_cta') OR length(_session)>80 OR NOT EXISTS(SELECT 1 FROM content_posts WHERE slug=_slug AND status='published' AND visibility='public' AND published_at<=now()) THEN RETURN false; END IF;
PERFORM pg_advisory_xact_lock(hashtext(_session));
IF EXISTS(SELECT 1 FROM content_events WHERE session_id=_session AND slug=_slug AND event_type=_event AND created_at>now()-interval '30 minutes') THEN RETURN false; END IF;
IF (SELECT count(*) FROM content_events WHERE session_id=_session AND created_at>now()-interval '1 day')>=100 THEN RETURN false; END IF;
INSERT INTO content_events(slug,path,event_type,session_id,props) VALUES(_slug,'/blog/'||_slug,_event,_session,jsonb_build_object('source',left(_source,120))); RETURN true; END $$;
REVOKE ALL ON FUNCTION public.blog_record_event(text,text,text,text) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.blog_record_event(text,text,text,text) TO service_role;
CREATE FUNCTION public.blog_delete_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF auth.role()='authenticated' AND NOT public.has_role('admin') THEN RAISE EXCEPTION 'Only administrators may delete posts'; END IF; RETURN OLD; END $$;
CREATE TRIGGER blog_delete_guard BEFORE DELETE ON public.content_posts FOR EACH ROW EXECUTE FUNCTION public.blog_delete_guard();